SELECT t.*, d.name AS dept_name, u.email AS author_email, s.email AS assignee_name
FROM tickets t
LEFT JOIN departments d ON d.id = t.department_id
LEFT JOIN users u ON u.id = t.author_id
LEFT JOIN users s ON s.id = t.assignee_id
WHERE t.department_id = #{deptId}
AND t.title LIKE '%' || #{titleKeyword} || '%'
AND t.closed = #{closed}
ORDER BY t.last_activity_at DESC LIMIT #{size} OFFSET #{offset}

SELECT t.*, d.name AS dept_name, u.email AS author_email, s.email AS assignee_name
FROM tickets t
LEFT JOIN departments d ON d.id = t.department_id
LEFT JOIN users u ON u.id = t.author_id
LEFT JOIN users s ON s.id = t.assignee_id
WHERE 1=1
AND t.title LIKE '%' || #{title} || '%'
AND t.ticket_code = #{ticketCode}
AND t.closed = #{closed}
AND t.created_at >= #{dateFrom}
AND t.created_at <= #{dateTo}
AND t.department_id = #{departmentId}
AND t.author_id = #{authorId}
AND t.author_id = #{ownerId}
AND (t.assignee_id IS NOT NULL) = #{assigned}
AND (t.title LIKE '%' || #{query} || '%' OR t.content LIKE '%' || #{query} || '%')
ORDER BY ${orderBy} LIMIT #{pageSize} OFFSET ${(page - 1) * pageSize}

SELECT COUNT(*) FROM tickets t
WHERE 1=1
AND t.title LIKE '%' || #{title} || '%'
AND t.ticket_code = #{ticketCode}
AND t.closed = #{closed}
AND t.created_at >= #{dateFrom}
AND t.created_at <= #{dateTo}
AND t.department_id = #{departmentId}
AND t.author_id = #{authorId}
AND t.author_id = #{ownerId}
AND (t.assignee_id IS NOT NULL) = #{assigned}
AND (t.title LIKE '%' || #{query} || '%' OR t.content LIKE '%' || #{query} || '%')
